Here's a basic example:

```cpp
#include <Windows.h>
#include <iostream>

// This function will be called when a keyboard event occurs
LRESULT CALLBACK KeyboardHookProc(int nCode, WPARAM wParam, LPARAM lParam)
{
    if (nCode >= 0 && (wParam == WM_KEYDOWN || wParam == WM_KEYUP))
    {
        // Log the key press here
        // You'll need to handle the logging yourself, for example, by writing to a file
        std::cout << "Key press: " << wParam << std::endl;
    }

    // Call the next hook in the hook chain
    return CallNextHookEx(NULL, nCode, wParam, lParam);
}

int main()
{
    // Create a keyboard hook
    HHOOK hHook = SetWindowsHookEx(WH_KEYBOARD_LL, KeyboardHookProc, NULL, 0);

    if (hHook == NULL)
    {
        std::cerr << "Error creating hook." << std::endl;
        return 1;
    }

    // Wait for the user to close the console
    std::cout << "Press Enter to close..." << std::endl;
    std::cin.get();

    // Unhook the keyboard hook
    UnhookWindowsHookEx(hHook);

    return 0;
}
